"use strict";function initReveal(){const e=document.querySelectorAll(".reveal");if(!e.length)return;const r=new IntersectionObserver(t=>{t.forEach(n=>{n.isIntersecting&&(n.target.classList.add("visible"),r.unobserve(n.target))})},{threshold:.12,rootMargin:"0px 0px -40px 0px"});e.forEach(t=>r.observe(t))}function initFAQ(){document.querySelectorAll(".faq__question").forEach(e=>{e.addEventListener("click",()=>{const r=e.getAttribute("aria-expanded")==="true";if(document.querySelectorAll(".faq__question").forEach(t=>{t.setAttribute("aria-expanded","false");const n=document.getElementById(t.getAttribute("aria-controls"));n&&n.classList.remove("open")}),!r){e.setAttribute("aria-expanded","true");const t=document.getElementById(e.getAttribute("aria-controls"));t&&t.classList.add("open")}})})}function initCounters(){const e=document.querySelectorAll("[data-count]");if(!e.length)return;const r=new IntersectionObserver(t=>{t.forEach(n=>{if(!n.isIntersecting)return;const s=n.target,a=parseInt(s.dataset.count,10);let o=0;const i=a/60,c=setInterval(()=>{o=Math.min(o+i,a),s.textContent=Math.floor(o).toLocaleString(),o>=a&&clearInterval(c)},16);r.unobserve(s)})},{threshold:.5});e.forEach(t=>r.observe(t))}function initTicker(){const e=document.querySelector(".ticker__track");e&&(e.addEventListener("mouseenter",()=>e.style.animationPlayState="paused"),e.addEventListener("mouseleave",()=>e.style.animationPlayState="running"))}
